CREATE TABLE candidate_rules (id INTEGER PRIMARY KEY, family_id INTEGER NOT NULL, version INTEGER NOT NULL, config TEXT NOT NULL, confirmed_by TEXT NOT NULL DEFAULT '', basis TEXT NOT NULL DEFAULT '', enabled INTEGER NOT NULL DEFAULT 0, enabled_by INTEGER REFERENCES users(id), enabled_at INTEGER, created_by INTEGER NOT NULL REFERENCES users(id), created_at INTEGER NOT NULL, UNIQUE(family_id,version));
CREATE TABLE candidate_results (id INTEGER PRIMARY KEY, comparison_id INTEGER NOT NULL REFERENCES paper_comparisons(id), rules_snapshot TEXT NOT NULL, result TEXT NOT NULL, created_by INTEGER NOT NULL REFERENCES users(id), created_at INTEGER NOT NULL);
